using System;using System.Threading.Tasks;using System.Linq;using UnityEngine;using Codice.Characters;using Codice.Presentation;using Codice.UI;
public static class ReviewThirdPerson
{
 public static async Task<string> Setup(){if(UnityEngine.SceneManagement.SceneManager.GetActiveScene().name!="Descenso")UnityEngine.SceneManagement.SceneManager.LoadScene("Descenso");for(int i=0;i<100&&(!RunHUD.Instance||!RunHUD.Instance.Player);i++)await Task.Delay(100);await Task.Delay(500);var p=RunHUD.Instance.Player;RunHUD.Instance.SetPaused(false);p.SetNarrativeControlsBlocked(false);p.State.Initialize(PlayerClass.Shinobi);await Task.Delay(200);p.enabled=false;p.GetComponent<PlayerCombat>().enabled=false;p.GetComponent<ActorPresentation>().enabled=false;p.GetComponent<ThirdPersonPresentation>().enabled=false;var mode=p.GetComponent<HumanPreviewCamera>();if(!mode.ThirdPerson)mode.Toggle();await Task.Delay(100);mode.enabled=false;var c=p.GetComponent<CharacterController>();c.enabled=false;p.transform.position=new Vector3(1000,1,1000);c.enabled=true;var body=p.GetComponent<ActorPresentation>().Body;body.speed=0;body.Play("Ready",0,0);body.Update(0);var light=new GameObject("Pose review light").AddComponent<Light>();light.type=LightType.Point;light.range=10;light.intensity=7;light.transform.position=p.transform.position+new Vector3(2,2,3);return "Ready";}
 public static string Pose(){var p=RunHUD.Instance.Player;var a=p.GetComponent<ActorPresentation>().Body;var camera=new GameObject("Pose review camera").AddComponent<Camera>();camera.transform.position=p.transform.position+new Vector3(2,1.4f,3);camera.transform.LookAt(p.transform.position+Vector3.up*.9f);camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.16f,.18f,.21f);camera.nearClipPlane=.05f;camera.farClipPlane=12;var rt=new RenderTexture(900,900,24);camera.targetTexture=rt;camera.Render();var prev=RenderTexture.active;RenderTexture.active=rt;var image=new Texture2D(900,900,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,900,900),0,0);image.Apply();System.IO.File.WriteAllBytes("Temp/third-person-review.png",image.EncodeToPNG());RenderTexture.active=prev;camera.targetTexture=null;UnityEngine.Object.Destroy(camera.gameObject);UnityEngine.Object.Destroy(rt);UnityEngine.Object.Destroy(image);return "Temp/third-person-review.png";}
}
